  ]}, legend:{enabled:false},
  xAxis:{type:'category', categories:series.map((_,i)=>mode==='weeks'?"'`${i+1} нед.`:`${i+1} окт.`), grid:{enabled:false}, lineVisible:false, ticks:{values:mode==='"'weeks'?[0,1,2,3,4]:[0,4,9,14,19,24,29]}, labels:{style:{fontSize:11}}},
