const DashboardContext = createContext({period: '30', edit: false, remove: (_id: string) => {}, notify: (_message: string) => {}, openDetail: (_detail: string) => {}});

function WidgetHeader({title, id, extra}: {title: string; id: string; extra?: React.ReactNode}) {
